[
  {
    "id": "obtain_cart_before_shopping",
    "text": "A shopper should obtain a cart before continuing the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartAcquired": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "Having a cart for a shopping trip is a layout-independent shopping convention and does not depend on any store coordinates."
  },
  {
    "id": "exit_with_cart",
    "text": "A shopper must not leave the store without the cart they were using.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "checkout": {
          "pre": "EXIT",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "checkout",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule refers only to the general act of exiting with or without a cart, so it applies across store layouts."
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper must not push a cart into a single-file aisle between shelves.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                },
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    },
    "justification": "The notion of a single-file shelf aisle is defined by local passage width and shelf adjacency rather than by particular cells."
  },
  {
    "id": "park_before_entering_single_file_aisle",
    "text": "A shopper must not move from a wider area into a single-file shelf aisle while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                },
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileAisleWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              {
                "not": "singleFileShelfAisle"
              }
            ]
          },
          "post": {
            "and": [
              "hasCart",
              "singleFileShelfAisle"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileAisleWithCart"
    },
    "justification": "This rule uses only the transition from a wider passage to a locally single-file shelf aisle, which can be recognized in any floor plan."
  },
  {
    "id": "no_cart_item_handling_in_single_file_aisle",
    "text": "A shopper must not interact with shelf items inside a single-file aisle while holding a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                },
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {
        "singleFileShelfInteraction": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileShelfInteraction",
          "hasCart"
        ]
      }
    },
    "justification": "The rule distinguishes item handling in locally constrained shelf aisles from ordinary shelf access without naming store-specific locations."
  },
  {
    "id": "retrieve_cart_after_cartless_single_file_pick",
    "text": "After entering a single-file shelf aisle without the cart to pick an item, the shopper must retrieve the cart before the trip ends.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                },
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {
        "cartlessSingleFileShelfPick": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "singleFileShelfAisle",
              "adjShelf",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartlessSingleFileShelfPick",
      "discharge": "hasCart"
    },
    "justification": "Retrieving a temporarily parked cart after visiting a narrow shelf aisle is a general shopping behaviour independent of aisle coordinates."
  },
  {
    "id": "do_not_drop_cart_beside_shelf",
    "text": "A shopper should not put down or abandon the cart directly beside a shelf.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartPutDown": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartPutDown",
          "adjShelf"
        ]
      }
    },
    "justification": "The constraint is expressed using the layout-independent relation of being adjacent to a shelf, not a particular parking cell."
  },
  {
    "id": "use_cart_for_accessible_shelf_items",
    "text": "If a shelf can be accessed from a cart-compatible passage rather than a single-file aisle, the shopper should interact with that shelf while keeping the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "or": [
            {
              "and": [
                {
                  "le": [
                    "freeWidthH",
                    1
                  ]
                },
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                {
                  "le": [
                    "freeWidthV",
                    1
                  ]
                },
                "shelfN",
                "shelfS"
              ]
            }
          ]
        },
        "cartAccessibleShelfFace": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {
        "cartAccessibleShelfInteraction": {
          "pre": {
            "and": [
              "cartAccessibleShelfFace",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "cartAccessibleShelfInteraction",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule contrasts cart-accessible shelf faces with locally single-file shelf aisles using geometric relations that transfer to other stores."
  }
]
